const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gbp=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format((n||0)/100);
const amount=n=>((n||0)/100).toFixed(2);
const admin=document.body.dataset.mode==='admin';
const realAdmin=document.body.dataset.role==='admin';
let state, page=location.hash.slice(1)||(admin?'dashboard':'appointments'), query='', busy=false, editor=null, period='month', from='',to='',calendarDay='',calendarMode='week', pendingPrint=null;
const labels={dashboard:'Dashboard',sales:'Total sales',appointments:admin?'Appointments':'Calendar',customers:'Customers',staff:'Staff',services:'Services',products:'Products / stock',cashups:'Cash-ups',reports:'Reports',settings:'Settings'};
const singular={customers:'customer',staff:'staff member',services:'service',products:'product',appointments:'appointment',sales:'sale',cashups:'cash-up',hours:'working hours',refunds:'refund',drawer:'drawer opening'};
const iconPaths={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',appointments:'M3 5h18v16H3zM3 10h18M8 3v4M16 3v4',customers:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-2a7 7 0 0 1 14 0v2M17 4a4 4 0 0 1 0 7M22 21v-2a6 6 0 0 0-4-6',staff:'M3 3h18v18H3zM12 12a3 3 0 1 0 0-6 3 3 0 0 0 0 6M7 19a5 5 0 0 1 10 0',services:'M6 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6M6 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6M8 8l13 12M8 16 21 3',products:'m3 7 9-4 9 4v13H3zM3 7h18M12 3v4M9 12h6',sales:'M2 5h20v14H2zM2 10h20M6 15h3',cashups:'M4 4h16v17H4zM7 8h10M7 12h2M15 12h2M7 16h2M15 16h2',reports:'M4 20V10M10 20V4M16 20v-7M22 20H2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[k]}"/></svg>`;
const match=r=>!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase());
const sum=(rows,key='total')=>rows.reduce((s,r)=>s+(r[key]||0),0);
const empty=(title,message)=>`<div class="empty"><strong>${title}</strong>${message}</div>`;
const statusName=status=>({in_progress:'Started',awaiting_payment:'Awaiting Payment',paid:'Paid',no_show:'No-show',booked:'Booked',arrived:'Arrived',completed:'Finished',cancelled:'Cancelled'}[status]||status);
const activeStaff=()=>state.staff.filter(s=>s.active!==false);
function catalogue(kind,includeId=''){const ids=Array.isArray(includeId)?includeId:[includeId];return (state[kind]||[]).filter(x=>x.active!==false||ids.includes(x.id));}
function onOff(active){return `<span class="badge ${active===false?'cancelled':''}">${active===false?'Inactive':'Active'}</span>`;}
const badge=status=>`<span class="badge ${/^[a-z0-9_]+$/.test(String(status))?status:''}">${esc(statusName(status))}</span>`;
function appointmentMinutes(time){const match=/^(\d{2}):(\d{2})$/.exec(String(time||''));return match?Number(match[1])*60+Number(match[2]):null;}
function appointmentBlocks(status){return status!=='cancelled'&&status!=='no_show';}
function staffBusyAt(staffId,date,start,duration,ignoreId=''){if(!staffId||!date||start==null||!(duration>0))return null;return (state.appointments||[]).find(item=>item.id!==ignoreId&&item.staff_id===staffId&&item.date===date&&appointmentBlocks(item.status)&&start<item.start+item.duration&&start+duration>item.start)||null;}
function staffDayWindow(staffId,date){
 if(!date)return [9*60,19*60];
 const hours=(state.hours||[]).find(row=>row.staff_id===staffId);
 if(!hours)return [9*60,19*60];
 const period=hours.days?.[new Date(date+'T12:00:00Z').getUTCDay()];
 if(!period?.start||!period?.end)return null;
 const open=appointmentMinutes(period.start),close=appointmentMinutes(period.end);
 if(open==null||close==null||close<=open)return null;
 return [open,close];
}
function bookingStartMinutes(staffId,date,duration,ignoreId){
 const window=staffDayWindow(staffId,date);
 if(!window)return [];
 const [open,close]=window;
 const marks=new Set();
 for(let minute=open;minute<close;minute+=15)marks.add(minute);
 if(staffId&&date){
  for(const item of state.appointments||[]){
   if(item.id===ignoreId||item.staff_id!==staffId||item.date!==date||!appointmentBlocks(item.status))continue;
   const end=item.start+item.duration;
   if(end>open&&end<close)marks.add(end);
  }
 }
 return [...marks].sort((a,b)=>a-b).filter(start=>{
  if(start<open||start>=close)return false;
  if(duration>0&&start+duration>close)return false;
  if(!staffId||!date)return true;
  return !staffBusyAt(staffId,date,start,duration>0?duration:1,ignoreId);
 });
}
function treatmentFits(staffId,date,start,duration,ignoreId){
 if(!(duration>0)||start==null)return true;
 const window=staffDayWindow(staffId,date);
 if(!window||start<window[0]||start+duration>window[1])return false;
 if(staffId&&date&&staffBusyAt(staffId,date,start,duration,ignoreId))return false;
 return true;
}
function fillBookingTimes(form,staffId,duration){
 const select=form.elements.time;
 if(!select||select.tagName!=='SELECT')return;
 const blocks=appointmentBlocks(form.elements.status?.value);
 const ignore=editor?.record?.id||'';
 const date=form.elements.date?.value||'';
 const chosen=select.value||select.dataset.picked||'';
 const chosenMinute=appointmentMinutes(chosen);
 const starts=blocks?bookingStartMinutes(staffId,date,duration,ignore):[];
 if(!blocks){const window=staffDayWindow(staffId,date)||[9*60,19*60];for(let minute=window[0];minute<window[1];minute+=15)starts.push(minute);}
 if(chosenMinute!=null&&!starts.includes(chosenMinute))starts.push(chosenMinute);
 starts.sort((a,b)=>a-b);
 const options=['<option value="">Select a start time</option>',...starts.map(start=>{
  const text=calendarClock(start);
  const fits=!blocks||treatmentFits(staffId,date,start,duration,ignore);
  const label=duration>0?`${text} to ${calendarClock(start+duration)}${fits?'':' — not free for this treatment'}`:text;
  return `<option value="${text}">${esc(label)}</option>`;
 })].join('');
 if(select.dataset.built===options)return;
 select.innerHTML=options;
 if(chosen&&[...select.options].some(option=>option.value===chosen))select.value=chosen;
 select.dataset.built=options;
}
function staffLiveStatus(member){if((state.appointments||[]).some(item=>item.staff_id===member.id&&item.status==='in_progress'))return 'Occupied';return member.active===false?'Inactive':'Available';}
function staffStatusBadge(member){const status=staffLiveStatus(member);const cls=status==='Occupied'?'occupied':status==='Inactive'?'cancelled':'available';return `<span class="badge ${cls}">${status}</span>`;}
function staffPhoto(member,large=false){const initial=esc(String(member.name||'?').trim().slice(0,1).toUpperCase()||'?');if(member.photo)return `<img class="${large?'staff-photo':'staff-avatar'}" src="/api/staff-photos/${esc(member.id)}?v=${member.version||0}" alt="">`;return `<span class="staff-fallback${large?' large':''}">${initial}</span>`;}
function staffPerson(member){return `<span class="staff-person">${staffPhoto(member)}<span><strong>${esc(member.name)}</strong>${member.job_title?`<small>${esc(member.job_title)}</small>`:''}</span></span>`;}
function staffStatusRow(team){if(!team.length)return '';return `<div class="staff-status-row" aria-label="Staff status">${team.map(member=>{const status=staffLiveStatus(member);return `<span class="staff-chip ${status.toLowerCase()}"><strong>${esc(member.name)}</strong><em>${status}</em></span>`;}).join('')}</div>`;}
function notify(message,error=false){$('#notice').hidden=false;$('#notice').className=error?'error':'';$('#notice').textContent=message;}
async function api(path,body){const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await response.json();if(response.status===401){location.replace('/');throw Error('Please sign in.');}if(!response.ok)throw Error(data.error||'Request failed.');return data;}
let workspaceStamp='',workspacePending=null,workspaceLoading=false,workspaceTimer=0;
function viewBusy(){if(busy)return true;if($('#record-dialog')?.open)return true;const el=document.activeElement;if(!el||el===document.body||el.id==='search')return false;return el.matches('input,textarea,select')||Boolean(el.closest('input,textarea,select'));}
function applyWorkspace(next,silent){const stamp=JSON.stringify(next);if(silent&&viewBusy()){workspacePending=next;return false;}if(stamp===workspaceStamp){workspacePending=null;return false;}workspacePending=null;workspaceStamp=stamp;state=next;if(!from)[from,to]=range('month');if(!calendarDay)calendarDay=state.today;return true;}
function renderFresh(){const scrolling=document.scrollingElement;const top=scrolling?.scrollTop||0,left=scrolling?.scrollLeft||0;render();if(scrolling){scrolling.scrollTop=top;scrolling.scrollLeft=left;}}
async function load(silent=false){if(workspaceLoading)return;workspaceLoading=true;try{const next=await api('/api/workspace');if(applyWorkspace(next,silent))renderFresh();}catch(error){if(!silent)throw error;}finally{workspaceLoading=false;}}
function flushWorkspace(){if(workspacePending&&!viewBusy())load(true);}
function range(type){const end=state.today;const d=new Date(end+'T12:00:00Z');if(type==='today')return [end,end];if(type==='week'){d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return [d.toISOString().slice(0,10),end];}if(type==='all')return ['0001-01-01',end];return [end.slice(0,7)+'-01',end];}
function salesBetween(start,end){return (state.sales||[]).filter(r=>r.date>=start&&r.date<=end);}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function actions(kind,row){return `<div class="row-actions"><button data-edit="${kind}" data-id="${esc(row.id)}">Edit<span class="sr-only"> ${esc(row.name||singular[kind])}</span></button>${admin||kind==='appointments'?`<button class="delete" data-delete="${kind}" data-id="${esc(row.id)}">Delete</button>`:''}</div>`;}
function navigation(){let sections=admin?[['GENERAL',['dashboard','appointments','customers','staff','services','products']],['FINANCE',['sales','cashups','reports']],['WORKSPACE',['settings']]]:[['STAFF MODE',['appointments','customers','sales','settings']]];$('#navigation').innerHTML=sections.map(([name,items])=>`<div class="nav-label">${name}</div>${items.map(k=>`<a class="nav-link ${page===k?'active':''}" ${page===k?'aria-current="page"':''} href="#${k}">${icon(k)}${!admin&&k==='sales'?'Walk-in sale':labels[k]}</a>`).join('')}`).join('');$('#profile-initial').textContent=admin?'A':'S';$('#profile-name').textContent=admin?'Admin':'Staff Mode';$('#profile-caption').textContent=admin?'Full workspace access':'Appointments & payments';$('.brand').href=admin?'/admin':'/staff';const modeLink=$('#mode-link');if(modeLink){modeLink.hidden=!(admin&&realAdmin);modeLink.href='/staff';modeLink.textContent='Staff Mode';}if(!admin)document.querySelectorAll('a[href="/admin"],a[href^="/admin/"]').forEach(link=>{link.hidden=true;link.removeAttribute('href');});}
function metric(label,value,note){return `<article class="metric"><h2>${label}</h2><strong>${value}</strong><p>${note}</p></article>`;}
function staffSummary(rows){const grouped=new Map();for(const r of rows){const lines=r.items.length?r.items:[{staff_id:r.staff_id,staff_name:r.staff_name,price:1,quantity:1}];const gross=lines.reduce((n,i)=>n+i.price*i.quantity,0);let used=0,usedCash=0;lines.forEach((i,index)=>{const last=index===lines.length-1,part=last?r.total-used:Math.floor(r.total*(i.price*i.quantity)/(gross||1)),cash=last?r.cash-usedCash:Math.floor(r.cash*(i.price*i.quantity)/(gross||1));used+=part;usedCash+=cash;const id=i.staff_id||r.staff_id,entry=grouped.get(id)||{name:i.staff_name||r.staff_name,total:0,cash:0,card:0,count:0};entry.total+=part;entry.cash+=cash;entry.card+=part-cash;entry.count++;grouped.set(id,entry);});}return [...grouped.values()].sort((a,b)=>b.total-a.total);}
function dashboard(){const daily=salesBetween(...range('today')),weekly=salesBetween(...range('week')),monthly=salesBetween(...range('month'));const appts=state.appointments.filter(x=>x.date===state.today&&x.status!=='cancelled'&&match(x)).sort((a,b)=>a.start-b.start);let days=[];for(let i=6;i>=0;i--){const d=new Date(state.today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-i);const key=d.toISOString().slice(0,10);days.push({day:d.toLocaleDateString('en-GB',{weekday:'short',timeZone:'UTC'}),total:sum(salesBetween(key,key))});}const max=Math.max(...days.map(x=>x.total),1);const staff=staffSummary(monthly);const low=state.products.filter(x=>x.active!==false&&x.stock<=x.reorder&&match(x));
return heading('Dashboard','Your salon at a glance. All figures are based on recorded sales.',`<span class="date-chip">${new Date(state.today+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'long',timeZone:'UTC'})}</span>`)+`<div class="metrics">${metric('Total sales',gbp(sum(state.sales)),'All recorded sales')}${metric('Daily revenue',gbp(sum(daily)),'Today')}${metric('Weekly revenue',gbp(sum(weekly)),'Monday to today')}${metric('Monthly revenue',gbp(sum(monthly)),'This calendar month')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><h2>Today’s appointments</h2><a href="#appointments">View all →</a></div>${appts.length?appts.map(x=>`<div class="appointment-item"><time>${esc(x.time)}</time><div><strong>${esc(x.customer_name)}</strong><small>${esc(x.services.map(s=>s.name).join(', '))} · ${esc(x.staff_name)}</small></div>${badge(x.status)}</div>`).join(''):empty('A clear schedule','Your appointments for today will appear here.')}</section><section class="panel"><div class="panel-title"><h2>Revenue statistics</h2><a href="#reports">Last 7 days →</a></div><div class="chart">${days.map(x=>`<div class="chart-column"><strong>${gbp(x.total)}</strong><div class="chart-track"><div class="chart-bar" style="height:${x.total/max*100}%"></div></div><small>${x.day}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-title"><h2>Cash & card totals</h2><a href="#cashups">Cash up →</a></div><p class="muted">Today’s recorded payments</p><div class="totals"><span>Cash<strong>${gbp(sum(daily,'cash'))}</strong></span><span>Card<strong>${gbp(sum(daily,'card'))}</strong></span></div><p class="muted">${daily.length} sale${daily.length===1?'':'s'} recorded today.</p></section><section class="panel"><div class="panel-title"><h2>Sales by staff member</h2><a href="#reports">This month →</a></div>${staff.length?table(['Staff member','Sales','Revenue'],staff.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.count}</td><td><strong>${gbp(x.total)}</strong></td></tr>`)):empty('No sales recorded yet','Sales will be attributed to the staff member selected at checkout.')}</section><section class="panel full"><div class="panel-title"><h2>Product stock alerts</h2><a href="#products">Manage stock →</a></div>${low.length?low.map(x=>`<div class="stock-row"><span>${esc(x.name)}<br><small>Alert level: ${x.reorder}</small></span><span class="badge warning">${x.stock} in stock</span></div>`).join(''):empty(state.products.length?'Stock levels look good':'Your stock starts here',state.products.length?'No products are at or below their alert level.':'Add your products and opening stock to see alerts here.')}</section></div>`;}
function filters(){return `<div class="filters"><label>Period<select id="period"><option value="today" ${period==='today'?'selected':''}>Daily</option><option value="week" ${period==='week'?'selected':''}>Weekly</option><option value="month" ${period==='month'?'selected':''}>Monthly</option><option value="all" ${period==='all'?'selected':''}>All time</option><option value="custom" ${period==='custom'?'selected':''}>Custom dates</option></select></label><label>From<input id="date-from" type="date" value="${from}" max="${to}"></label><label>To<input id="date-to" type="date" value="${to}" min="${from}"></label><button class="secondary" id="export-sales">Export CSV</button></div>`;}
function saleTable(rows){return table(['Date / customer','Staff member','Items','Total','Cash / card','Actions'],rows.map(r=>`<tr><td>${r.date}<small>${esc(r.customer_name)}</small></td><td>${esc(r.staff_name)}</td><td>${r.items.map(i=>`${esc(i.name)} × ${i.quantity}`).join('<br>')}</td><td><strong>${gbp(r.total)}</strong></td><td>${gbp(r.cash)} / ${gbp(r.card)}</td><td>${actions('sales',r)}</td></tr>`));}
function reports(){const rows=salesBetween(from,to).filter(match),staff=staffSummary(rows);const days=new Map();rows.forEach(x=>{const d=days.get(x.date)||{total:0,cash:0,card:0,count:0};d.total+=x.total;d.cash+=x.cash;d.card+=x.card;d.count++;days.set(x.date,d);});return heading('Reports','Revenue by date and staff member. Dates use Europe/London.')+filters()+`<div class="metrics">${metric('Revenue',gbp(sum(rows)),'Selected period')}${metric('Cash payments',gbp(sum(rows,'cash')),'Net cash retained')}${metric('Card payments',gbp(sum(rows,'card')),'Recorded terminal payments')}${metric('Number of sales',rows.length,'Selected period')}</div><div class="dashboard-grid"><section class="panel full"><h2 class="table-title">Sales by staff member</h2>${staff.length?table(['Staff member','Sales','Cash','Card','Total'],staff.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.count}</td><td>${gbp(x.cash)}</td><td>${gbp(x.card)}</td><td><strong>${gbp(x.total)}</strong></td></tr>`)):empty('No sales in this period','Try another date range or record a sale.')}</section><section class="panel full"><h2 class="table-title">Daily revenue</h2>${days.size?table(['Date','Sales','Cash','Card','Total'],[...days].sort((a,b)=>b[0].localeCompare(a[0])).map(([day,x])=>`<tr><td>${day}</td><td>${x.count}</td><td>${gbp(x.cash)}</td><td>${gbp(x.card)}</td><td><strong>${gbp(x.total)}</strong></td></tr>`)):empty('No revenue yet','Daily totals appear as sales are recorded.')}</section></div>`;}
function recordsView(kind){const rows=state[kind].filter(r=>match(r)&&(kind!=='appointments'||r.date===calendarDay));const subtitle={customers:'Customer contact details and notes.',staff:'Add each person with their details and a photo. They appear on the staff calendar straight away. Everyone on the desk still uses the shared staff PIN.',services:'Prices are the published website prices. A name marked “from” books at that starting price. Sunbed times and the 30-minute EMS session are printed on the website. Other durations are a starting diary length you can edit here. Inactive services stay on past bookings.',products:'Enter the selling price, cost, stock, low-stock level and supplier. A completed sale reduces stock.',appointments:`Bookings for ${calendarLabel(calendarDay,{weekday:'long',day:'numeric',month:'long'})}. Day and Week show the same bookings on the calendar.`,cashups:admin?'Reconcile the day’s cash. A saved cash-up closes that date to sales changes.':'Reconcile cash for the selected day, including refunds.'}[kind];let headers, cells;
if(kind==='customers'){headers=['Full name','Mobile','Email','Notes','Actions'];cells=r=>[esc(r.name),esc(r.phone)||'—',esc(r.email)||'—',esc(r.notes)||'—',`<button class="secondary" data-customer="${r.id}">View history</button>`+actions(kind,r)];}
if(kind==='staff'){headers=['Staff member','Mobile','Status','Actions'];cells=r=>[staffPerson(r),esc(r.phone)||'—',staffStatusBadge(r),actions(kind,r)];}
if(kind==='services'){headers=['Service','Category','Price','Duration','Status','Actions'];cells=r=>[esc(r.name),esc(r.category)||'—',gbp(r.price),`${r.duration} min`,onOff(r.active),actions(kind,r)];}
if(kind==='products'){headers=['Product','Category','Selling price','Cost','Stock','Low stock','Supplier','Status','Actions'];cells=r=>[esc(r.name),esc(r.category)||'—',gbp(r.price),gbp(r.cost||0),r.stock<=r.reorder?`<span class="badge warning">${r.stock} · Low stock</span>`:r.stock,r.reorder,esc(r.supplier)||'—',onOff(r.active),actions(kind,r)];}
if(kind==='appointments'){rows.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));headers=['Date / time','Customer','Staff / service','Status',...(admin?['Total']:[]),'Actions'];cells=r=>[`${r.date}<small>${r.time} · ${r.duration} min</small>`,esc(r.customer_name),`${esc(r.staff_name)}<small>${esc(r.services.map(x=>x.name).join(', '))}</small>`,badge(r.status),...(admin?[gbp(r.total)]:[]),actions(kind,r)+(r.paid?'<span class="badge">Paid</span>':!['cancelled','no_show'].includes(r.status)?`<div class="row-actions"><button data-checkout="${r.id}">Take payment</button></div>`:'')];}
if(kind==='cashups'){headers=['Date / person','Opening cash','Cash sales','Cash refunds','Expected cash','Actual cash','Over / short','Notes'];cells=r=>[`${r.date}<small>${esc(r.completed_by||'')}<br>${r.at?new Date(r.at).toLocaleString('en-GB'):''}</small>`,gbp(r.opening),gbp(r.cash),gbp(r.refunds),gbp(r.expected),gbp(r.counted),`${gbp(Math.abs(r.difference))} ${r.difference>0?'over':r.difference<0?'short':'balanced'}`,esc(r.notes)+(admin?actions(kind,r):'')];}
return (kind==='appointments'?calendarControls()+staffStatusRow(activeStaff()): '')+heading(labels[kind],subtitle,`<button class="primary" data-new="${kind}">+ ${kind==='cashups'?'Cash up':`Add ${singular[kind]}`}</button>`)+`<section class="panel">${rows.length?table(headers,rows.map(r=>`<tr>${cells(r).map(c=>`<td>${c}</td>`).join('')}</tr>`)):empty(`No ${kind==='staff'?'staff members':labels[kind].toLowerCase()} ${query?'found':'yet'}`,query?'Try another search.':`Add your first ${singular[kind]} to get started.`)}</section>`;}
function settingsFields(record){return `<div class="field-grid">${field('name','Business name',record.name,'text',true)}${field('phone','Phone',record.phone)}${field('address','Address',record.address,'textarea')}</div>`;}
function hardwarePanel(){const hw=state.hardware||{},usb=hw.connection==='usb';return `<section class="panel hardware-card"><h2>Receipt printer and cash drawer</h2><p class="muted">${esc(hw.printer||'Star TSP143IV UE')} · ${esc(hw.printerDetail||'USB and Ethernet thermal receipt printer')}<br>${esc(hw.drawer||'14×16 in. printer-driven cash drawer')} · ${esc(hw.drawerDetail||'Plugs into the DK port on the printer.')}</p><ol class="hardware-steps"><li>Plug the cash drawer cable into the DK port on the back of the Star printer. The till does not plug into the Mac.</li><li>Connect the printer with the Ethernet cable, or with the USB cable to this Mac, and switch it on.</li><li>For Ethernet, hold Feed while switching the printer on. Enter the address printed on the network slip.</li></ol><form id="hardware-form"><div class="field-grid"><label class="field">Connection<select name="connection" id="printer-connection"><option value="ethernet" ${usb?'':'selected'}>Ethernet</option><option value="usb" ${usb?'selected':''}>USB</option></select></label><label class="check wide"><input type="checkbox" name="enabled" ${hw.enabled?'checked':''}>Use this printer for receipts and to open the till</label><label class="field wide" id="printer-host-field" ${usb?'hidden':''}>Printer address<input name="host" value="${esc(hw.host||'')}" placeholder="192.168.1.50" inputmode="decimal" autocomplete="off" spellcheck="false"></label><label class="field wide" id="printer-usb-field" ${usb?'':'hidden'}>USB printer queue<input name="usbQueue" value="${esc(hw.usbQueue||'')}" placeholder="Star_TSP143" autocomplete="off" spellcheck="false"></label></div><div class="hardware-actions"><button class="primary" type="submit">Save hardware</button><button class="secondary" type="button" id="find-printers" ${usb?'':'hidden'}>Look for USB printers</button><button class="secondary" type="button" id="test-connection">Test connection</button><button class="secondary" type="button" id="test-print">Print a test receipt</button><button class="secondary" type="button" data-new="drawer">Open the till</button></div></form><p class="muted">A cash payment asks the printer to open the till. Card payments do not. Printing a receipt does not open the till. Test buttons use the details on this form. Sales use the saved connection. ${hw.enabled?'Printer saved and ready.':'Printer not saved for use yet.'}</p></section>`;}
function hardwareFormBody(){const form=$('#hardware-form'),data=Object.fromEntries(new FormData(form));data.enabled=form.elements.enabled.checked;return data;}
async function findPrinters(){try{const data=await api('/api/hardware/queues');if(!data.queues.length){notify('No USB printer queue was found. Add the Star printer in System Settings, then look again.',true);return;}if(data.queues.length===1)$('#hardware-form').elements.usbQueue.value=data.queues[0];notify(data.queues.length===1?`Found ${data.queues[0]}. Save hardware to use it.`:`USB printers: ${data.queues.join(', ')}`);}catch(error){notify(error.message,true);}}
