if(kind==='sales'){const a=appointment;$('#dialog-title').textContent=editor.type==='deposit'?'Record deposit':record?'Edit sale':'Record payment';html=select('staff_id','Staff member',state.staff.filter(x=>x.active!==false||x.id===r.staff_id),r.staff_id||a?.staff_id)+select('customer_id','Customer',state.customers,r.customer_id||a?.customer_id,false)+field('date','Sale date',r.date||state.today,'date',true,`max="${state.today}"`)+`<label class="field">Payment method<select name="method"><option value="cash" ${r.method==='cash'?'selected':''}>CASH</option><option value="card" ${r.method==='card'?'selected':''}>CARD</option></select></label>`;}
