function updateAppointment(){
 const f=$('#record-form'),summary=$('#appointment-summary');if(!f||!summary)return;
 const ids=new FormData(f).getAll('service_ids'),services=ids.map(id=>editor.record?.services.find(s=>s.id===id)||state.services.find(s=>s.id===id)).filter(Boolean);
 const total=sum(services,'price'),duration=sum(services,'duration');
 const named=String(f.elements.new_staff_name?.value||'').trim().toLowerCase();
 const staffId=f.elements.staff_id?.value||state.staff.find(person=>String(person.name||'').trim().toLowerCase()===named)?.id||'';
 fillBookingTimes(f,staffId,duration);
 const start=appointmentMinutes(f.elements.time?.value);
 const blocks=appointmentBlocks(f.elements.status?.value);
 const clash=blocks?staffBusyAt(staffId,f.elements.date?.value,start,duration,editor.record?.id):null;
 const window=staffDayWindow(staffId,f.elements.date?.value);
 const outside=blocks&&duration>0&&start!=null&&(window===null||start<window[0]||start+duration>window[1]);
 const save=$('#save-record');if(save&&!busy)save.disabled=Boolean(clash||outside||(blocks&&duration>0&&start==null));
 const staffName=state.staff.find(person=>person.id===staffId)?.name||String(f.elements.new_staff_name?.value||'').trim();
 const warning=clash?`<p class="error" id="appointment-clash">This staff member already has an appointment at that time (${esc(clash.time)}–${calendarClock(clash.start+clash.duration)}, ${esc(clash.customer_name)}). This treatment needs ${duration} minutes, so choose a start that is free for the whole treatment.</p>`:'';
 const hoursWarning=!clash&&outside?`<p class="error" id="appointment-hours">${window?`This treatment runs until ${calendarClock(start+duration)}, after this staff member finishes at ${calendarClock(window[1])}.`:'This staff member is not working on that day.'}</p>`:'';
 const hold=duration>0&&start!=null&&!clash&&!outside?`<span id="appointment-hold">Holds ${esc(staffName||'this staff member')} <strong>${calendarClock(start)}–${calendarClock(start+duration)}</strong></span>`:'';
 summary.innerHTML=warning+hoursWarning+hold+`<span>Total duration <strong>${duration} minutes</strong></span><span>Total price <strong>${gbp(total)}</strong></span><span>Deposit received <strong>${gbp(editor.record?.deposit||0)}</strong></span><span>Remaining balance <strong>${gbp(total-(editor.record?.deposit||0))}</strong></span><small>Save the appointment, then use Record deposit to record cash or card received. The minutes beside each treatment are how long that staff member is blocked. Another booking for the same person can start when this one ends. Number of people does not multiply service prices or duration. A price marked “from” is the published starting price.</small>`;
}
function addLine(item={}){const row=document.createElement('div');row.className='sale-line';row.innerHTML=`<select aria-label="Sale item" class="item-choice" required><option value="">Choose service or product…</option>${saleChoices(item)}</select><input class="item-quantity" aria-label="Quantity" type="number" value="${item.quantity||1}" min="1" max="1000" required><select class="item-staff" aria-label="Staff for item" required>${activeStaff().map(person=>`<option value="${person.id}" ${person.id===(item.staff_id||editor.appointment?.staff_id||$('#record-form').elements.staff_id.value)?'selected':''}>${esc(person.name)}</option>`).join('')}</select><button type="button" class="icon-button remove-line" aria-label="Remove item">×</button>`;$('#sale-lines').append(row);}
function saleItems(){return [...document.querySelectorAll('.sale-line')].map(row=>{const [kind,id]=row.querySelector('select').value.split(':');return {kind,id,quantity:Number(row.querySelector('input').value),staff_id:row.querySelector('.item-staff').value};});}
function saleTotal(){if(editor.type==='deposit')return Math.round(Number($('#record-form').elements.deposit_amount?.value||0)*100);return saleItems().reduce((s,item)=>{const original=editor.record?.items.find(x=>x.kind===item.kind&&x.id===item.id);const booked=editor.appointment?.services.find(x=>item.kind==='services'&&x.id===item.id);return s+(original?.price??booked?.price??state[item.kind]?.find(x=>x.id===item.id)?.price??0)*(Number.isFinite(item.quantity)?item.quantity:0);},0);}
function updateSale(){if(!$('#sale-summary'))return;const f=$('#record-form'),method=f.elements.method.value,gross=saleTotal(),deposit=editor.type==='deposit'?0:(editor.appointment?.deposit||editor.record?.deposit_applied||0),discount=editor.type==='deposit'?0:Math.round(Number(f.elements.discount.value||0)*100),total=gross-discount-deposit;f.elements.cash.closest('label').hidden=method!=='split';f.elements.cash.disabled=method!=='split';f.elements.tendered.closest('label').hidden=method==='card';f.elements.tendered.disabled=method==='card';$('#card-confirmation').hidden=method==='cash';f.elements.card_confirmed.required=method!=='cash';const cash=method==='cash'?total:method==='card'?0:Math.round(Number(f.elements.cash.value)*100)||0;const received=Math.round(Number(f.elements.tendered.value)*100)||0;$('#sale-summary').innerHTML=`<span>Subtotal ${gbp(gross)}</span><span>Discount ${gbp(discount)}</span><strong>Total ${gbp(gross-discount)}</strong><span>Deposit already paid ${gbp(deposit)}</span><strong>Amount remaining ${gbp(total)}</strong><span>${method==='card'?'Card payment':`Change ${gbp(Math.max(0,received-cash))}`}</span>`;}
async function updateCashup(){const f=$('#record-form'),day=f.elements.date.value;if(!day)return;try{const totals=await api('/api/cash-summary/'+day);if(editor?.kind!=='cashups'||f.elements.date.value!==day)return;const opening=Math.round(Number(f.elements.opening.value||0)*100),actual=Math.round(Number(f.elements.counted.value||0)*100),expected=opening+totals.cash-totals.refunds,difference=actual-expected;$('#cashup-summary').innerHTML=`<span>Cash sales <strong>${gbp(totals.cash)}</strong></span><span>Cash refunds <strong>${gbp(totals.refunds)}</strong></span><span>Expected cash <strong>${gbp(expected)}</strong></span><span>${difference>0?'Over':difference<0?'Short':'Balanced'} <strong>${gbp(Math.abs(difference))}</strong></span>`;}catch(error){$('#form-error').textContent=error.message;}}
function receipt(sale){editor=null;$('#form-error').textContent='';$('#dialog-title').textContent='Sale completed';$('#save-record').hidden=true;$('#cancel-dialog').textContent='Done';$('#fields').innerHTML=`<div class="receipt"><h2>${esc(sale.businessName||'Beauty For All')}</h2><p>${sale.businessAddress?esc(sale.businessAddress).replaceAll('\n','<br>'):'277 Blagreaves Lane<br>DE23 1PT'}${sale.businessPhone?`<br>${esc(sale.businessPhone)}`:''}</p><strong>Receipt ${esc(sale.receipt_number||sale.id)}</strong><p>${sale.at?new Date(sale.at).toLocaleString('en-GB',{timeZone:'Europe/London'}):sale.date}<br>Staff: ${esc([...new Set(sale.items.map(i=>i.staff_name||sale.staff_name))].join(', ')||sale.staff_name)}<br>Customer: ${esc(sale.customer_name)}</p>${sale.items.length?table(['Item','Qty','Price','Amount'],sale.items.map(x=>`<tr><td>${esc(x.name)}${x.staff_name?`<small>${esc(x.staff_name)}</small>`:''}</td><td>${x.quantity}</td><td>${gbp(x.price)}</td><td>${gbp(x.price*x.quantity)}</td></tr>`)):'<p>Appointment deposit</p>'}<p>Subtotal: ${gbp(sale.gross_total??sale.total)}${sale.discount?`<br>Discount: ${gbp(sale.discount)}`:''}<br><strong>Total: ${gbp((sale.gross_total??sale.total)-(sale.discount||0))}</strong>${sale.deposit_applied?`<br>Deposit already paid: ${gbp(sale.deposit_applied)}`:''}<br>Paid now: ${gbp(sale.total)}<br>Payment: ${esc(sale.method.toUpperCase())}${sale.cash?`<br>Cash received: ${gbp(sale.tendered)}<br>Change: ${gbp(sale.change)}`:''}</p><p>Thank you for visiting Beauty For All!</p></div><div class="receipt-actions">${state.hardware?.enabled?`<button type="button" class="primary" id="print-receipt-button" data-sale="${esc(sale.id)}">Print on receipt printer</button><button type="button" class="secondary" id="browser-print-button">Print from this browser</button>`:`<button type="button" class="primary" id="print-receipt-button">Print receipt</button>`}</div>${sale.drawer_status?`<p class="muted">Drawer: ${esc({not_connected:'not connected',command_sent:'command sent',failed:'command failed; ask an admin',already_requested:'previous request retained'}[sale.drawer_status])}.</p>`:''}`;const receiptDialog=$('#record-dialog');if(!receiptDialog.open)receiptDialog.showModal();receiptDialog.scrollTop=0;}
function deleteDialog(kind,r){if(kind==='services'&&!admin){notify('Only an admin can delete a service from the list.',true);return;}editor={kind,record:r,remove:true};$('#dialog-title').textContent=`Delete ${singular[kind]}?`;$('#fields').innerHTML=`<p class="muted">Delete ${esc(r.name||`${singular[kind]} from ${r.date||''}`)}? This removes it from active records.${kind==='appointments'?' It leaves the calendar and keeps the customer.':''}${kind==='sales'?' It leaves the sales totals, puts product stock back, updates a linked appointment, and never reuses this receipt number. This does not refund a card or return cash.':''}${kind==='cashups'?' This reopens the date for sales changes.':''}</p>`;$('#form-error').textContent='';$('#save-record').textContent='Delete record';$('#save-record').hidden=false;$('#cancel-dialog').textContent='Cancel';$('#record-dialog').showModal();$('#record-dialog').scrollTop=0;}
async function bookingPerson(kind,id,name,phone){if(kind==='staff'){const member=(state.staff||[]).find(row=>row.id===id);if(!member)throw Error('Choose a staff member. An admin adds people under Staff.');if(member.active===false&&editor?.record?.staff_id!==id)throw Error('That staff member is inactive. Ask an admin to make them active.');return id;}const trimmed=String(name||'').trim();if(kind==='customers'&&trimmed)id='';if(id)return id;if(!trimmed)throw Error('Enter the customer’s name.');const existing=(state.customers||[]).find(row=>String(row.name||'').trim().toLowerCase()===trimmed.toLowerCase());if(existing)return existing.id;const saved=await api('/api/records/customers',{name:trimmed,phone:phone||''});state.customers.unshift(saved);return saved.id;}
$('#record-form').addEventListener('click',event=>{if(event.target.id!=='staff-photo-clear'||!editor)return;event.preventDefault();editor.clearPhoto=true;editor.photoData='';const field=event.target.closest('.staff-photo-field');const current=field?.querySelector('img, .staff-fallback');const fallback=document.createElement('span');fallback.className='staff-fallback large';fallback.textContent=String(editor.record?.name||'?').trim().slice(0,1).toUpperCase()||'?';if(current)current.replaceWith(fallback);const input=$('#staff-photo-file');if(input)input.value='';});$('#record-form').addEventListener('change',event=>{if(event.target.id!=='staff-photo-file'||!editor)return;const file=event.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1500000){$('#form-error').textContent='Use a JPEG, PNG or WebP photo under 1.5 MB.';event.target.value='';return;}$('#form-error').textContent='';const reader=new FileReader();reader.onload=()=>{editor.photoData=String(reader.result||'');editor.clearPhoto=false;const field=event.target.closest('.staff-photo-field');const old=field.querySelector('img, .staff-fallback');const img=document.createElement('img');img.className='staff-photo';img.alt='';img.src=editor.photoData;old.replaceWith(img);};reader.readAsDataURL(file);});$('#record-form').addEventListener('submit',async event=>{event.preventDefault();if(busy||!editor)return;busy=true;$('#save-record').disabled=true;$('#form-error').textContent='';try{const form=event.currentTarget;let data=Object.fromEntries(new FormData(form));const {kind,record,appointment}=editor;if(editor.remove)data={action:'delete'};else if(kind==='hours')data.days=Array.from({length:7},(_,i)=>data['start_'+i]||data['end_'+i]?{start:data['start_'+i],end:data['end_'+i]}:null);else if(kind==='drawer')data.request_key=editor.request_key;else if(kind==='refunds')data.confirmed=form.elements.confirmed.checked;else if(kind==='staff'){if(editor.clearPhoto)data.photo='';else if(editor.photoData)data.photo=editor.photoData;}else if(kind==='appointments'){data.service_ids=new FormData(form).getAll('service_ids');if(!data.service_ids.length)throw Error('Tick at least one service.');const duration=data.service_ids.reduce((total,id)=>total+(record?.services?.find(service=>service.id===id)?.duration??state.services.find(service=>service.id===id)?.duration??0),0);const named=String(data.new_staff_name||'').trim().toLowerCase();const staffId=data.staff_id||state.staff.find(person=>String(person.name||'').trim().toLowerCase()===named)?.id||'';if(appointmentBlocks(data.status)&&staffBusyAt(staffId,data.date,appointmentMinutes(data.time),duration,record?.id))throw Error('This staff member already has an appointment at that time.');data.customer_id=await bookingPerson('customers',data.customer_id,data.new_customer_name,data.mobile);data.save_customer_phone=true;data.staff_id=await bookingPerson('staff',data.staff_id,data.new_staff_name);delete data.new_customer_name;delete data.new_staff_name;}else if(kind==='sales'){if(!appointment&&!record&&data.new_customer_name?.trim()){const customer=await api('/api/records/customers',{name:data.new_customer_name,phone:data.new_customer_phone,email:data.new_customer_email});state.customers.unshift(customer);form.elements.customer_id.add(new Option(customer.name,customer.id));form.elements.customer_id.value=customer.id;data.customer_id=customer.id;form.elements.new_customer_name.value='';}data.items=editor.type==='deposit'?[]:saleItems();data.type=editor.type;data.card_confirmed=form.elements.card_confirmed.checked;data.appointment_id=record?.appointment_id||appointment?.id||'';data.request_key=editor.request_key;}if(record){data.id=record.id;data.version=record.version;}const saved=await api(`/api/records/${kind}`,data);if(kind==='drawer'){$('#record-dialog').close();notify(`Drawer: ${saved.status.replaceAll('_',' ')}. Request logged.`);editor=null;return;}const showReceipt=kind==='sales'&&!editor.remove;await load();if(showReceipt){receipt(saved);if(state.hardware?.enabled&&saved.id)pendingPrint=saved.id;}else{$('#record-dialog').close();notify(`${singular[kind][0].toUpperCase()+singular[kind].slice(1)} ${editor.remove?'deleted':'saved'}.`);editor=null;}}catch(error){$('#form-error').textContent=error.message;}finally{busy=false;$('#save-record').disabled=false;if(editor?.kind==='appointments'&&!editor.remove)updateAppointment();if(pendingPrint){const id=pendingPrint;pendingPrint=null;sendToPrinter(id);}}});
$('#record-form').addEventListener('input',()=>{if(editor?.kind==='appointments'){if(document.activeElement?.id==='service-filter')filterServices();updateAppointment();}if(editor?.kind==='sales')updateSale();if(editor?.kind==='cashups')updateCashup();});
$('#record-form').addEventListener('change',event=>{if(editor?.kind==='appointments'){if(event.target.name==='customer_id')$('#record-form').elements.mobile.value=state.customers.find(c=>c.id===event.target.value)?.phone||'';if(event.target.name==='service_ids')filterServices();updateAppointment();}if(editor?.kind==='sales')updateSale();if(editor?.kind==='cashups')updateCashup();});
$('#record-form').addEventListener('click',event=>{if(event.target.closest('#browser-print-button')||(event.target.closest('#print-receipt-button')&&!state.hardware?.enabled)){browserPrint();return;}if(event.target.closest('#print-receipt-button')){sendToPrinter(event.target.closest('#print-receipt-button').dataset.sale);return;}const action=event.target.closest('[data-appointment-action]');if(action){appointmentAction(action.dataset.appointmentAction,action.dataset.id);return;}if(event.target.closest('#add-line')){addLine();updateSale();}const remove=event.target.closest('.remove-line');if(remove){remove.closest('.sale-line').remove();updateSale();}});
function closeDialog(){if(!busy){$('#record-dialog').close();editor=null;}}
$('#record-dialog').addEventListener('close',()=>{$('#print-output')?.remove();flushWorkspace();});
$('#close-dialog').onclick=closeDialog;$('#cancel-dialog').onclick=closeDialog;$('#record-dialog').addEventListener('cancel',event=>{if(busy)event.preventDefault();});
$('#view').addEventListener('click',event=>{if(event.target.closest('#desk-sale')){deskClick(event);return;}const button=event.target.closest('button');if(!button)return;if(!admin&&['services','staff'].includes(button.dataset.new||button.dataset.edit||button.dataset.delete)){notify(button.dataset.new==='staff'||button.dataset.edit==='staff'||button.dataset.delete==='staff'?'Only an admin can add or change a staff member.':'Only an admin can change or delete a service. Add or remove it on the booking.',true);return;}if(button.id==='find-printers'){findPrinters();return;}if(button.id==='test-connection'){testHardware('test-connection','Printer connection succeeded.');return;}if(button.id==='test-print'){testHardware('test-print','Test receipt sent to the printer. The till stays closed.');return;}if(button.dataset.customer)showCustomer(button.dataset.customer);if(button.dataset.appointment)showAppointment(button.dataset.appointment);if(button.dataset.slot){const [staff_id,time]=button.dataset.slot.split('|');if(staffBusyAt(staff_id,calendarDay,appointmentMinutes(time),1)){notify('This staff member already has an appointment at that time.',true);return;}openEditor('appointments',null,null,{staff_id,time,date:calendarDay});}if(button.dataset.openDay){calendarDay=button.dataset.openDay;calendarMode='day';render();}if(button.dataset.dayStep){const step=calendarMode==='week'?Number(button.dataset.dayStep)*7:Number(button.dataset.dayStep);calendarDay=calendarShift(calendarDay,step);render();}if(button.id==='calendar-today'){calendarDay=state.today;calendarMode='day';render();}if(button.dataset.calendarView&&['day','week','list'].includes(button.dataset.calendarView)){calendarMode=button.dataset.calendarView;render();}if(button.dataset.new)openEditor(button.dataset.new,null,null,button.dataset.new==='appointments'?{date:calendarDay}:{});if(button.dataset.edit)openEditor(button.dataset.edit,state[button.dataset.edit].find(x=>x.id===button.dataset.id));if(button.dataset.delete)deleteDialog(button.dataset.delete,state[button.dataset.delete].find(x=>x.id===button.dataset.id));if(button.dataset.checkout){const appointment=state.appointments.find(x=>x.id===button.dataset.checkout);if(state.sales?.some(x=>x.appointment_id===appointment.id)){notify('This appointment has already been paid.',true);return;}openEditor('sales',null,appointment);}if(button.id==='export-sales')exportSales();});
$('#view').addEventListener('change',event=>{if(event.target.id==='printer-connection'){const usb=event.target.value==='usb';$('#printer-host-field').hidden=usb;$('#printer-usb-field').hidden=!usb;$('#find-printers').hidden=!usb;}if(event.target.id==='calendar-date'){if(event.target.value){calendarDay=event.target.value;render();}}if(event.target.id==='period'){period=event.target.value;if(period!=='custom')[from,to]=range(period);render();}if(['date-from','date-to'].includes(event.target.id)){const next=event.target.value;if(!next)return;const a=event.target.id==='date-from'?next:from,b=event.target.id==='date-to'?next:to;if(a>b){notify('The start date must be on or before the end date.',true);render();return;}from=a;to=b;period='custom';render();}});
$('#view').addEventListener('input',event=>{if(!event.target.closest('#desk-sale'))return;syncDeskFromForm();if(event.target.name==='q'){$('#desk-tiles').innerHTML=deskCatalogue();return;}updateDeskTotals();});$('#view').addEventListener('change',event=>{if(!event.target.closest('#desk-sale'))return;syncDeskFromForm();updateDeskTotals();});$('#view').addEventListener('keydown',event=>{if(event.target.name==='q'&&event.key==='Enter')event.preventDefault();});$('#view').addEventListener('submit',async event=>{if(event.target.id==='desk-sale'){submitDeskSale(event);return;}if(event.target.id==='hardware-form'){event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{state.hardware=await api('/api/hardware',hardwareFormBody());await load();notify('Printer and till settings saved.');}catch(error){notify(error.message,true);}finally{button.disabled=false;}return;}if(['staff-pin-form','admin-pin-form','recovery-form','mail-form'].includes(event.target.id)){event.preventDefault();const form=event.target;const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));let path='/api/access/staff-pin',message='New staff PIN saved. The previous staff PIN no longer works.';if(form.id==='admin-pin-form'){path='/api/access/admin-pin';message='Admin PIN changed.';}else if(form.id==='recovery-form'){path='/api/access/recovery';message='Recovery details saved.';}else if(form.id==='mail-form'){path='/api/access/mail';data.enabled=form.elements.enabled.checked;data.port=Number(data.port);message='';}const result=await api(path,data);await load();notify(form.id==='mail-form'?(result.mailConfigured?'Mailbox saved. Reset links can be emailed.':'Mailbox saved. It is switched off, so a reset email will not be sent.'):message);}catch(error){notify(error.message,true);}finally{button.disabled=false;}return;}if(event.target.id!=='settings-form')return;event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{await api('/api/records/settings',{...Object.fromEntries(new FormData(event.target)),id:state.settings.id,version:state.settings.version});await load();notify('Settings saved.');}catch(error){notify(error.message,true);}finally{button.disabled=false;}});
function exportSales(){const rows=salesBetween(from,to).filter(match);const cell=value=>'"'+String(value).replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const lines=[['Date','Customer','Staff','Total GBP','Cash GBP','Card GBP'],...rows.map(r=>[r.date,r.customer_name,r.staff_name,amount(r.total),amount(r.cash),amount(r.card)])];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`beauty-for-all-sales-${from}-${to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1);query='';$('#search').value='';$('#notice').hidden=true;render();});$('#search').addEventListener('input',event=>{query=event.target.value;render();});$('#new-appointment').onclick=()=>openEditor('appointments',null,null,{date:calendarDay});
async function logout(){try{await api('/api/logout',{});location.replace('/');}catch(error){notify(error.message,true);}}$('#logout').onclick=logout;const mobileLogout=document.createElement('button');mobileLogout.className='secondary mobile-signout';mobileLogout.textContent='Sign out';mobileLogout.onclick=logout;$('.toolbar-actions').append(mobileLogout);
window.addEventListener('pageshow',event=>{if(event.persisted)location.reload();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)load(true);});document.addEventListener('focusout',()=>setTimeout(flushWorkspace,0));load().then(()=>{clearInterval(workspaceTimer);workspaceTimer=setInterval(()=>load(true),2000);}).catch(error=>{notify(error.message,true);$('#view').innerHTML=empty('Unable to load your workspace','Refresh the page to try again.');});
